UPDATE HDOC_SEND_DATA_VIN_PLATE
SET STATUS = '0'
WHERE SERIE = #{serie}
  AND CHNR = #{chnr}

UPDATE HDOC_SEND_DATA_VIN_PLATE
SET STATUS = '1'
WHERE SERIE = #{serie}
  AND CHNR = #{chnr}

UPDATE HDOC_SEND_DATA_VIN_PLATE
SET STATUS = '0',
    TYPE = '1'
WHERE SERIE = #{serie}
  AND CHNR = #{chnr}

UPDATE HDOC_SEND_DATA_VIN_PLATE
SET STATUS = '0',
    TYPE = '2'
WHERE SERIE = #{serie}
  AND CHNR = #{chnr}
